import { useCallback, useEffect, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import { Bell, CheckCheck, X } from 'lucide-react'
import { notificationService } from '../services/notification.service.js'
import { relativeTime } from '../lib/time.js'
import { useAuth } from '../context/AuthContext.jsx'
import { EmptyState, Skeleton } from '../ui/states.jsx'

/* Notification inbox popover. Notifications are generated by services at the
   moment an event happens, so every entry links to a real record. */
export default function NotificationInbox({ align = 'right' }) {
  const { user } = useAuth()
  const [open, setOpen] = useState(false)
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(false)
  const [unread, setUnread] = useState(0)
  const panelRef = useRef(null)
  const buttonRef = useRef(null)

  const load = useCallback(async () => {
    if (!user) return
    setLoading(true)
    try {
      const result = await notificationService.listForUser(user.id)
      setItems(result.items)
      setUnread(result.unreadCount)
    } catch {
      setItems([])
    } finally {
      setLoading(false)
    }
  }, [user])

  useEffect(() => {
    load()
  }, [load])

  useEffect(() => {
    if (!open) return
    const onClick = (event) => {
      if (panelRef.current?.contains(event.target) || buttonRef.current?.contains(event.target)) return
      setOpen(false)
    }
    const onKey = (event) => event.key === 'Escape' && setOpen(false)
    document.addEventListener('mousedown', onClick)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onClick)
      document.removeEventListener('keydown', onKey)
    }
  }, [open])

  const markAll = async () => {
    if (!user) return
    await notificationService.markAllRead(user.id)
    setItems((current) => current.map((item) => ({ ...item, read: true })))
    setUnread(0)
  }

  const markOne = async (id) => {
    await notificationService.markRead(id)
    setItems((current) => current.map((item) => (item.id === id ? { ...item, read: true } : item)))
    setUnread((current) => Math.max(0, current - 1))
  }

  return (
    <div className="relative">
      <button
        ref={buttonRef}
        type="button"
        onClick={() => setOpen((value) => !value)}
        className="icon-btn relative"
        aria-label={`Notifications${unread ? `, ${unread} unread` : ''}`}
        aria-expanded={open}
        aria-haspopup="dialog"
      >
        <Bell className="h-4 w-4" />
        {unread > 0 ? (
          <span className="absolute -right-0.5 -top-0.5 flex h-[15px] min-w-[15px] items-center justify-center rounded-full bg-[var(--ink)] px-1 text-[9px] font-semibold text-white">
            {unread > 9 ? '9+' : unread}
          </span>
        ) : null}
      </button>

      {open ? (
        <div
          ref={panelRef}
          role="dialog"
          aria-label="Notifications"
          className={`absolute top-[42px] z-50 w-[min(92vw,358px)] overflow-hidden rounded-[16px] border border-[var(--line)] bg-white shadow-[var(--shadow-lg)] ${
            align === 'right' ? 'right-0' : 'left-0'
          }`}
        >
          <div className="flex items-center justify-between border-b border-[var(--line)] px-3.5 py-2.5">
            <p className="text-[12.5px] font-medium text-ink">
              Notifications {unread > 0 ? <span className="text-soft">· {unread} unread</span> : null}
            </p>
            <div className="flex items-center gap-1">
              <button
                type="button"
                onClick={markAll}
                disabled={!unread}
                className="inline-flex items-center gap-1 rounded-full px-2 py-1 text-[11px] text-muted transition hover:bg-[var(--surface-sunken)] disabled:opacity-40"
              >
                <CheckCheck className="h-3 w-3" /> Mark all read
              </button>
              <button type="button" onClick={() => setOpen(false)} className="rounded-full p-1 text-soft hover:text-ink" aria-label="Close notifications">
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>

          <div className="thin-scroll max-h-[330px] overflow-y-auto">
            {loading ? (
              <div className="space-y-2 p-3">
                <Skeleton className="h-10" />
                <Skeleton className="h-10" />
                <Skeleton className="h-10" />
              </div>
            ) : items.length === 0 ? (
              <EmptyState compact icon={Bell} title="You are all caught up" description="New examinations, class starts and replies will appear here." />
            ) : (
              items.map((item) => (
                <Link
                  key={item.id}
                  to={item.link || '#'}
                  onClick={() => {
                    if (!item.read) markOne(item.id)
                    setOpen(false)
                  }}
                  className={`flex gap-2.5 border-b border-[var(--line)] px-3.5 py-2.5 transition last:border-0 hover:bg-[var(--sky-50)] ${
                    item.read ? '' : 'bg-[var(--cream-50)]'
                  }`}
                >
                  <span className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${item.read ? 'bg-transparent' : 'bg-[var(--ink)]'}`} />
                  <span className="min-w-0">
                    <span className="block text-[12px] font-medium leading-snug text-ink">{item.title}</span>
                    <span className="mt-0.5 block text-[11.5px] leading-snug text-muted clamp-2">{item.body}</span>
                    <span className="mt-1 block text-[10px] uppercase tracking-wide text-soft">{relativeTime(item.createdAt)}</span>
                  </span>
                </Link>
              ))
            )}
          </div>
        </div>
      ) : null}
    </div>
  )
}
